const { branch, author, path, since, until, maxResults } = $.input;
const params = {
  per_page: String(Math.max(1, Math.min(100, maxResults || 20)))
};
if (branch) params.sha = branch;
if (author) params.author = author;
if (path) params.path = path;
if (since) params.since = since;
if (until) params.until = until;
return { params };

const resp = $.steps.listCommits.response || [];
const commits = (Array.isArray(resp) ? resp : []).map(c => ({
  sha: c.sha,
  shortSha: c.sha?.substring(0, 7) || '',
  message: c.commit?.message || '',
  messageFirstLine: (c.commit?.message || '').split('\n')[0],
  author: {
    name: c.commit?.author?.name || '',
    email: c.commit?.author?.email || '',
    login: c.author?.login || '',
    date: c.commit?.author?.date || ''
  },
  committer: {
    name: c.commit?.committer?.name || '',
    login: c.committer?.login || ''
  },
  stats: c.stats || null,
  url: c.html_url,
  verified: c.commit?.verification?.verified || false
}));

// Build summary stats
const authors = [...new Set(commits.map(c => c.author.login || c.author.name).filter(Boolean))];
const dateRange = commits.length > 0
  ? { from: commits[commits.length - 1].author.date, to: commits[0].author.date }
  : null;

return {
  commits,
  totalFound: commits.length,
  repo: $.input.owner + '/' + $.input.repo,
  branch: $.input.branch || 'default',
  uniqueAuthors: authors,
  dateRange,
  filters: {
    author: $.input.author || 'any',
    path: $.input.path || 'any',
    since: $.input.since || 'any',
    until: $.input.until || 'any'
  },
  summary: 'Found ' + commits.length + ' commit' + (commits.length === 1 ? '' : 's') + ' in ' + $.input.owner + '/' + $.input.repo + ($.input.branch ? ' on ' + $.input.branch : '') + ' by ' + authors.length + ' author' + (authors.length === 1 ? '' : 's')
};
